const GR_TABS8={city:'Město a hosté',standards:'Standardy',subscriptions:'Předplatné',temporary:'Dočasné provozy',expansion:'Expanze regionů'};
function grToast8(action,after){try{action();persist();render();if(after)after();}catch(e){toast(e.message);}}
function growthDialog8(tab='city',city=gameCity6){grTab8=tab;grCitySelection8=city;show(`<span class="eyelabel">RŮST FIRMY</span><h2>${esc(GR_TABS8[tab])}</h2><div class="tabs gr-tabs8">${Object.entries(GR_TABS8).map(([k,n])=>`<button class="${k===tab?'active':''}" data-gr-tab8="${k}">${esc(n)}</button>`).join('')}</div><div id="grBody8"></div>`);document.querySelectorAll('[data-gr-tab8]').forEach(b=>b.onclick=()=>growthDialog8(b.dataset.grTab8,grCitySelection8));({city:grCityUI8,standards:grStandardsUI8,subscriptions:grSubscriptionsUI8,temporary:grTemporaryUI8,expansion:grExpansionUI8}[tab])();}
function grCityUI8(){const city=grCitySelection8,enabled=state.growth8.cities.includes(city),list=LOCATIONS.filter(l=>l.city===city);el('grBody8').innerHTML=`<div class="fields">${field('Město',`<select id="grCity8">${cityOptions(city)}</select>`)}</div><p class="sub">Kanceláře, škola a zastávka mění ranní, polední a odpolední návštěvy. Blízkost je model sousedství; budovy představují zdroje hostů, které nelze koupit. Zapnutí ovlivní skutečnou frontu a rozpis od dalšího týdne.</p><button class="${enabled?'soft':'primary'}" id="grCityToggle8">${enabled?'Pozastavit proudy v tomto městě':'Zapnout proudy hostů'}</button><div class="gr-source-list8">${citySources8(city).map(x=>`<span>${esc(x.name)}</span>`).join('')}</div><div class="table-scroll"><table class="data"><thead><tr><th>Adresa</th><th>Ráno</th><th>Poledne</th><th>Odpoledne</th><th>Vliv okolí</th></tr></thead><tbody>${list.map(l=>{const f=cityFlow8(l.id);return `<tr><td><button class="quiet" data-gr-flow8="${l.id}">${esc(l.name)}</button></td>${f.periods.map(p=>`<td>${Math.round(p*100)} %</td>`).join('')}<td>${Math.round((f.foot-1)*100)} % hostů</td></tr>`;}).join('')}</tbody></table></div><p class="sub">Procenta jsou rozdělení celého dne do 7–11, 11–15 a 15–19. Počasí, cena, reputace a soupeři se dál počítají samostatně.</p>`;el('grCity8').onchange=()=>growthDialog8('city',el('grCity8').value);el('grCityToggle8').onclick=()=>grToast8(()=>setCityLife8(city,!enabled),()=>growthDialog8('city',city));document.querySelectorAll('[data-gr-flow8]').forEach(b=>b.onclick=()=>grFlowDialog8(b.dataset.grFlow8));}
function grFlowDialog8(id){const f=cityFlow8(id);show(`<h2>${esc(loc(id).name)} · odkud přicházejí hosté</h2>${rows(f.sources.map(s=>[s.name,s.distance===0?'Ve stejném sousedství':s.distance+' sousedství daleko']))}<div class="gr-periods8">${f.periods.map((n,i)=>`<div><strong>${Math.round(n*100)} %</strong><span>${['Ráno 7–11','Poledne 11–15','Odpoledne 15–19'][i]}</span><i style="--flow:${n*100}%"></i></div>`).join('')}</div><p class="sub">${f.enabled?'Proudy jsou aktivní pro skutečný provoz.':'Proudy zatím nejsou zapnuté; toto je návrh rozložení.'} Vliv okolí ${Math.round((f.foot-1)*100)} %. Špičky mohou zhoršit frontu, když neposílíš skutečnou směnu.</p><div class="actions"><button class="soft" id="grFlowCity8">Správa města</button><button class="primary" id="grFlowMap8">Vybrat na mapě</button></div>`);el('grFlowCity8').onclick=()=>growthDialog8('city',f.city);el('grFlowMap8').onclick=()=>{el('modal').close();gameReturn6(id);};}
function grStandardsUI8(){const stores=state.stores.filter(s=>!s.franchise&&!grTemporary8(s.id)),g=state.growth8;el('grBody8').innerHTML=`<p class="sub">Ulož menu, vlastní interiér, vybavení, kávu a rozpis z dobře fungující pobočky. Při zavádění se mění jedna kavárna týdně. Chybějící tým a ruční rozpis zastaví krok; lidé se nevytvářejí automaticky.</p><div class="fields">${field('Vzorová kavárna',`<select id="grStandardSource8">${stores.map(s=>option(s.id,loc(s.id).name)).join('')}</select>`)}${field('Název standardu',`<input id="grStandardName8" value="Standard značky" maxlength="40">`)}</div><button class="primary" id="grCapture8" ${!stores.length?'disabled':''}>Uložit standard a návrh kavárny</button>${!stores.length?'<p class="sub">Nejdřív otevři stálou vlastní kavárnu. Vlastní návrh můžeš předem připravit ve Studiu.</p>':''}<div class="gr-cards8">${g.standards.map(x=>`<article><strong>${esc(x.name)}</strong><p>${esc(brand(x.brand).name)} · ${x.shifts.join(' / ')} baristů · ${esc(blend(x.blend).name)}</p><p class="sub">Vzor ${esc(loc(x.source).name)} · uložená revize ${x.revision}. Návrh najdeš také při otevírání kavárny.</p><button class="soft" data-gr-standard8="${x.id}">Prověřit pobočky a zavedení</button></article>`).join('')}</div><h3>Zavádění</h3>${g.rollouts.slice(-12).reverse().map(p=>`<article class="gr-item8"><strong>${esc(p.standard.name)} · ${p.steps.length} / ${p.targets.length}</strong><p>${esc(p.reason)}</p><small>${money(p.spent)} / ${money(p.budget)} · ${esc({active:'Běží',completed:'Dokončeno',cancelled:'Zastaveno'}[p.status])}</small>${p.status==='active'?`<button class="quiet" data-gr-stop8="${p.id}">Zastavit další změny</button>`:''}</article>`).join('')||'<p class="sub">Zatím bez naplánovaného zavádění.</p>'}`;el('grCapture8').onclick=()=>grToast8(()=>captureStandard8(el('grStandardSource8').value,el('grStandardName8').value),()=>growthDialog8('standards'));document.querySelectorAll('[data-gr-standard8]').forEach(b=>b.onclick=()=>grRolloutDialog8(b.dataset.grStandard8));document.querySelectorAll('[data-gr-stop8]').forEach(b=>b.onclick=()=>grToast8(()=>stopRollout8(b.dataset.grStop8),()=>growthDialog8('standards')));}
function grRolloutDialog8(id){const x=grStandard8(id),targets=state.stores.filter(s=>!s.franchise&&s.brand===x.brand&&!grTemporary8(s.id));show(`<h2>${esc(x.name)} · zavádění standardu</h2><div class="gr-targets8">${targets.map(s=>{try{const q=standardAudit8(x,s.id);return `<label><input type="checkbox" data-gr-target8="${s.id}" ${q.compliant?'':'checked'}> <span>${esc(loc(s.id).name)} · ${q.compliant?'Splňuje standard':money(q.cost)}${q.crewGap?' · chybí '+q.crewGap+' úvazků':''}${q.manual?' · ruční rozpis':''}</span></label>`;}catch(e){return `<p>${esc(loc(s.id).name)} · ${esc(e.message)}</p>`;}}).join('')}</div><div class="fields">${field('Celkový limit',`<input id="grRolloutBudget8" type="number" min="0" max="10000000" value="500000">`)}${field('Provozní rezerva · týdny',`<input id="grRolloutReserve8" type="number" min="1" max="8" value="3">`)}</div><button class="primary" id="grRolloutQuote8">Zkontrolovat plán a cenu</button>`);el('grRolloutQuote8').onclick=()=>{try{const ids=[...document.querySelectorAll('[data-gr-target8]:checked')].map(b=>b.dataset.grTarget8),q=rolloutQuote8(id,ids,Number(el('grRolloutBudget8').value),Number(el('grRolloutReserve8').value));show(`<h2>Zavést ${esc(x.name)}</h2>${rows(q.rows.map(r=>[r.name,money(r.cost)+(r.crewGap?' · čeká na tým':'')]))}${rows([['Maximální dnešní cena',money(q.cost)],['Schválený celkový limit',money(q.budget)],['Provozní rezerva',money(q.reserved)]])}<p class="sub">Schválíš placené změny po jedné pobočce týdně. Cena každého kroku se znovu ověří; limit a rezerva platí po celou dobu. Zastavení zabrání dalším změnám.</p><button class="primary" id="grRolloutApprove8" ${!q.safe?'disabled':''}>Schválit postupné zavedení</button>${!q.safe?'<p class="bad">Chybí hotovost, limit nebo mandát boardu.</p>':''}`);el('grRolloutApprove8').onclick=()=>grToast8(()=>startRollout8(id,ids,q.budget,q.reserve,q),()=>growthDialog8('standards'));}catch(e){toast(e.message);}};}
function grSubscriptionsUI8(){const g=state.growth8,products=state.products6.catalog.filter(p=>p.status==='released'),ready=state.projects.eshop.done&&state.departments.it&&products.length;el('grBody8').innerHTML=`<p class="sub">Předplatitel dostává 1–4 sáčky vlastní kávy každý týden nebo jednou za čtyři týdny. Expedice spotřebuje hotová balení, platí se skutečné poštovné a doručení trvá týden. Tržba vznikne až doručením; výpadky, kvalita a cena ovlivní odchody.</p><button class="primary" id="grNewSubscription8" ${!ready?'disabled':''}>Navrhnout předplatné</button>${!ready?'<p class="sub">Potřebuješ uvedený produkt, hotový e-shop a tým IT.</p><button class="soft" id="grPrepareProducts8">Připravit produkty</button>':''}<div class="gr-cards8">${g.subscriptions.map(s=>{const p=product6(s.product),orders=g.shipments.filter(o=>o.subscription===s.id&&o.status==='transit'),last=s.last,delivered=g.shipments.filter(o=>o.subscription===s.id&&o.status==='delivered').at(-1);return `<article><strong>${esc(s.name)}</strong><p>${esc(p.name)} · ${s.units} × ${p.size} g · ${money(s.price)} za zásilku · ${s.interval===1?'týdně':'každé 4 týdny'}</p>${rows([['Předplatitelé',s.customers+' / '+s.cap],['Nejbližší expedice','T'+s.next],['Na cestě',orders.reduce((n,o)=>n+o.customers,0)+' zásilek'],['Poslední doručení · příspěvek',delivered?money(delivered.sale.contribution):'—']])}${last?`<p class="sub">T${last.week}: +${last.joined} nových, −${last.left} odchodů; ${last.shipped} odesláno, ${last.missing} nepokryto. Marketing ${money(last.marketing)}.</p>`:''}<div class="actions">${s.status!=='cancelled'?`<button class="soft" data-gr-sub8="${s.id}" data-status="${s.status==='active'?'paused':'active'}">${s.status==='active'?'Pozastavit':'Obnovit'}</button><button class="quiet" data-gr-sub8="${s.id}" data-status="cancelled">Ukončit</button>`:'<span>Ukončeno</span>'}<button class="quiet" data-gr-orders8="${s.id}">Zásilky a marže</button></div></article>`;}).join('')||'<p class="sub">Zatím žádné předplatné. Marketing získává zákazníky postupně; samotné založení žádné nepřidává.</p>'}`;if(el('grNewSubscription8'))el('grNewSubscription8').onclick=grNewSubscription8;if(el('grPrepareProducts8'))el('grPrepareProducts8').onclick=()=>{el('modal').close();coffeeTab6='products';goto('coffee');};document.querySelectorAll('[data-gr-sub8]').forEach(b=>b.onclick=()=>grToast8(()=>setSubscriptionStatus8(b.dataset.grSub8,b.dataset.status),()=>growthDialog8('subscriptions')));document.querySelectorAll('[data-gr-orders8]').forEach(b=>b.onclick=()=>grOrdersUI8(b.dataset.grOrders8));}
function grNewSubscription8(){const products=state.products6.catalog.filter(p=>p.status==='released');show(`<h2>Nové kávové předplatné</h2><div class="fields">${field('Název',`<input id="grSubName8" value="Káva domů" maxlength="40">`)}${field('Produkt',`<select id="grSubProduct8">${products.map(p=>option(p.id,p.name+' · '+p.size+' g')).join('')}</select>`)}${field('Sáčky v zásilce',`<input id="grSubUnits8" type="number" min="1" max="4" value="2">`)}${field('Interval',`<select id="grSubInterval8"><option value="4">Každé 4 týdny</option><option value="1">Každý týden</option></select>`)}${field('Cena celé zásilky včetně pošty a DPH',`<input id="grSubPrice8" type="number" min="50" max="4000" value="480">`)}${field('Týdenní marketing',`<input id="grSubMarketing8" type="number" min="0" max="20000" value="2000">`)}${field('Limit předplatitelů',`<input id="grSubCap8" type="number" min="1" max="500" value="50">`)}${field('Rezerva · týdny',`<input id="grSubReserve8" type="number" min="1" max="8" value="3">`)}</div><button class="primary" id="grSubQuote8">Spočítat marži a zřízení</button>`);el('grSubQuote8').onclick=()=>{try{const data={name:el('grSubName8').value,product:el('grSubProduct8').value,units:Number(el('grSubUnits8').value),interval:Number(el('grSubInterval8').value),price:Number(el('grSubPrice8').value),marketing:Number(el('grSubMarketing8').value),cap:Number(el('grSubCap8').value),reserve:Number(el('grSubReserve8').value)},q=subscriptionQuote8(data);show(`<h2>${esc(data.name)} · ekonomika jedné zásilky</h2>${rows([['Cena hostovi s poštou a DPH',money(data.price)],['Tržba bez DPH',money(q.net)],['Káva · dnešní vlastní šarže',money(q.coffee)],['Balení',money(q.packing)],['Poštovné',money(q.shipping)],['Platební poplatek',money(q.handling)],['Odhad příspěvku před marketingem',money(q.margin)],['Zřízení · platba nyní',money(q.cost)],['Pravidelný marketing',money(data.marketing)+'/týden']])}<p class="sub">Odhad vychází z dnešní kávy. Balení se připravuje v Produkty a balení; automatický plán potřebuje vlastní rozpočet a kávu. Zásilky na cestě se doručí i po pozastavení.</p><button class="primary" id="grSubApprove8" ${!q.safe?'disabled':''}>Zaplatit zřízení ${money(q.cost)}</button>`);el('grSubApprove8').onclick=()=>confirmAction('Založit předplatné?',data.name+' · '+money(q.cost)+' nyní · marketing nejvýše '+money(data.marketing)+' týdně při zachování rezervy.',()=>createSubscription8(data,q),'Založit a zaplatit');}catch(e){toast(e.message);}};}
function grOrdersUI8(id){const s=state.growth8.subscriptions.find(x=>x.id===id),orders=state.growth8.shipments.filter(o=>o.subscription===id).slice(-20).reverse();show(`<h2>${esc(s.name)} · skutečné zásilky</h2>${orders.map(o=>`<article class="gr-item8"><strong>${o.customers} ${o.customers===1?'zásilka':o.customers<5?'zásilky':'zásilek'} · ${o.units} ${o.units===1?'sáček':o.units<5?'sáčky':'sáčků'} · T${o.created} → T${o.due}</strong><p>${o.status==='transit'?'Na cestě · zatím bez tržby':'Doručeno T'+o.delivered}</p>${rows([['Spotřebovaná balení',money(o.cost)],['Zaplacené poštovné',money(o.shipping)],['Tržba bez DPH',o.sale?money(o.sale.revenue):'—'],['Příspěvek po kávě, balení a poště',o.sale?money(o.sale.contribution):'—']])}</article>`).join('')||'<p>Zatím žádná skutečná expedice.</p>'}<button class="soft" id="grOrdersBack8">Zpět k předplatným</button>`);el('grOrdersBack8').onclick=()=>growthDialog8('subscriptions');}
function grTemporaryUI8(){const g=state.growth8;el('grBody8').innerHTML=`<p class="sub">Ověř lokalitu na 2–12 týdnů. Truck má vlastní přenosné vybavení a po testu zůstane zaparkovaný. Dočasná kavárna vybavení po skončení odprodá. Skutečný tým, mzdy, káva, fronty a výsledky se vedou stejně jako u poboček.</p><button class="primary" id="grNewTemporary8">Navrhnout test lokality</button><div class="gr-cards8">${g.venues.map(v=>`<article><strong>${esc(GR_VENUE_TYPES8[v.type].name)} · ${esc(loc(v.location).name)}</strong><p>${esc({active:'Běží do T'+v.until,idle:'Zaparkovaný vlastní truck',closed:'Test ukončen'}[v.status])}</p><p class="sub">${esc(v.reason)}</p>${v.last?rows([['Poslední týden · hosté',v.last.served+' / '+v.last.demand],['Výsledek testu za '+v.trials.length+' týdnů',money(v.trials.reduce((n,r)=>n+r.profit,0))],['Průměr hostů / týden',Math.round(v.trials.reduce((n,r)=>n+r.served,0)/v.trials.length)]]) :'<p class="sub">Výsledky vzniknou po prvním skutečném týdnu.</p>'}<div class="actions">${v.status==='active'?`<button class="soft" data-gr-map8="${v.location}">Provoz a tým</button><button class="soft" data-gr-extend8="${v.id}">Prodloužit o 4 týdny</button><button class="quiet" data-gr-close8="${v.id}">Ukončit test</button>`:v.status==='idle'?`<button class="primary" data-gr-reuse8="${v.id}">Nasadit na další místo</button>`:''}<button class="quiet" data-gr-trial8="${v.id}">Výsledky jednotlivých týdnů</button>${v.status!=='active'&&grFree8(v.location)?`<button class="soft" data-gr-permanent8="${v.location}">Připravit stálou kavárnu</button>`:''}</div></article>`).join('')}</div>`;el('grNewTemporary8').onclick=()=>grTemporaryDialog8();document.querySelectorAll('[data-gr-map8]').forEach(b=>b.onclick=()=>{el('modal').close();gameReturn6(b.dataset.grMap8);});document.querySelectorAll('[data-gr-extend8]').forEach(b=>b.onclick=()=>{const v=grVenue8(b.dataset.grExtend8),q={id:v.id,weeks:4,until:v.until,week:state.week,cash:state.cash,cost:GR_VENUE_TYPES8[v.type].permit};confirmAction('Prodloužit test?',money(q.cost)+' za nové povolení. Pravidelné mzdy, zásoby a provoz zůstávají.',()=>extendTemporary8(v.id,4,q),'Zaplatit a prodloužit');});document.querySelectorAll('[data-gr-close8]').forEach(b=>b.onclick=()=>{const q=temporaryCloseQuote8(b.dataset.grClose8);confirmAction('Ukončit dočasný provoz?', 'Odstupné '+money(q.fee)+', vrácená hodnota '+money(q.refund)+'. '+(grVenue8(q.id).type==='truck'?'Truck zůstává majetkem. ':'')+'Tým se vrací na trh práce.',()=>closeTemporary8(q.id,q),'Uzavřít test');});document.querySelectorAll('[data-gr-reuse8]').forEach(b=>b.onclick=()=>grTemporaryDialog8(null,b.dataset.grReuse8));document.querySelectorAll('[data-gr-trial8]').forEach(b=>b.onclick=()=>{const v=grVenue8(b.dataset.grTrial8);show(`<h2>${esc(loc(v.location).name)} · historie testů</h2>${rows(v.trials.map(r=>['T'+r.week+' · '+loc(r.location).name,r.served+' hostů · '+money(r.profit)]))}<p class="sub">Výsledek pobočky zahrnuje mzdy, zásoby a provoz, nezahrnuje jednorázové zřízení a konečné odstupné. Ty byly hrazeny firmou. Změny počasí a konkurence mohou výsledek stálé kavárny změnit.</p>`);});document.querySelectorAll('[data-gr-permanent8]').forEach(b=>b.onclick=()=>openDialog(b.dataset.grPermanent8));}
function grTemporaryDialog8(address=null,reuse=null){const old=reuse&&grVenue8(reuse),free=LOCATIONS.filter(l=>grFree8(l.id));show(`<h2>${old?'Nasadit vlastní truck':'Test nové lokality'}</h2><div class="fields">${field('Druh provozu',`<select id="grTempType8" ${old?'disabled':''}>${Object.entries(GR_VENUE_TYPES8).map(([k,v])=>option(k,v.name,old?.type)).join('')}</select>`)}${field('Volná adresa',`<select id="grTempAddress8">${free.map(l=>option(l.id,l.city+' · '+l.name,address||free[0]?.id)).join('')}</select>`)}${field('Délka testu · týdny',`<input id="grTempWeeks8" type="number" min="2" max="12" value="4">`)}</div><p class="sub">Povolení se vztahuje k této adrese. Provoz začne po zřízení, kávu musíš fyzicky dodat. Po skončení testu se provoz uzavře a vyúčtuje odstupné.</p><button class="primary" id="grTempQuote8" ${!free.length?'disabled':''}>Prověřit vybavení, tým a celý start</button>`);el('grTempQuote8').onclick=()=>{try{const type=el('grTempType8').value,id=el('grTempAddress8').value,weeks=Number(el('grTempWeeks8').value),q=temporaryQuote8(type,id,weeks,reuse);show(`<h2>${esc(GR_VENUE_TYPES8[type].name)} · ${esc(loc(id).name)}</h2>${rows([['Vybavení a přenosný provoz',money(q.capital)],['Povolení a nábor',money(q.fee)],['Celý start se zásobami a rezervou',money(q.required)],['Platba nyní',money(q.cost)],['Model provozních nákladů / týden',money(q.running)],['Rezervované závěrečné odstupné',money(q.closing)],['Doba testu',weeks+' týdnů']])}<p class="sub">Skuteční kandidáti: ${esc(q.staffPids.map(pid=>state.baristaCandidates.find(p=>p.pid===pid).name).join(', '))}. Káva není součástí dnešní platby; sjednej ji po zřízení. Rezerva počítá dvě místní dodávky po 25 kg.</p><button class="primary" id="grTempApprove8" ${!q.safe?'disabled':''}>Zřídit za ${money(q.cost)}</button>${!q.safe?'<p class="bad">Nemáš prostředky na celý bezpečný test nebo mandát boardu.</p>':''}`);el('grTempApprove8').onclick=()=>confirmAction('Zřídit dočasný provoz?',loc(id).name+' · '+money(q.cost)+' nyní. Káva a provoz se hradí ze zbývající rezervy.',()=>startTemporary8(type,id,weeks,reuse,q),'Zřídit a zaplatit');}catch(e){toast(e.message);}};}
function grExpansionUI8(){const regions=state.regions.filter(r=>r.manager),g=state.growth8;el('grBody8').innerHTML=`<p class="sub">Regionální ředitel připravuje až tři reálné nabídky podle limitu, zisku a návratnosti. Návrhy nic neplatí ani nerezervují. Zakladatel schválí konkrétní cenu; pak běží skutečná příprava, nábor a zásobení.</p><button class="primary" id="grExpansionPolicy8" ${!regions.length?'disabled':''}>Nastavit pověření regionu</button>${!regions.length?'<p class="sub">Nejdřív zajisti kancelář a regionálního ředitele v Lidé & regiony.</p><button class="soft" id="grExpansionPeople8">Obsadit vedení regionu</button>':''}${g.delegation.map(p=>`<article class="gr-item8"><strong>${esc(p.city)} · ${p.enabled?'Pověření aktivní':'Pozastaveno'}</strong><p>Limit ${money(p.budget)} · použito na schválené starty ${money(p.committed)} · zisk od ${money(p.minProfit)} / týden · návratnost do ${p.maxPayback} týdnů</p><button class="soft" data-gr-propose8="${p.city}">Připravit nabídky nyní</button></article>`).join('')}<h3>Nabídky a schválené přípravy</h3>${g.offers.slice(-16).reverse().map(o=>`<article class="gr-item8"><strong>${esc(o.quote.author)} · ${esc(loc(o.location).name)}</strong><p>${money(o.quote.required)} celý start a rezerva firmy · model ${money(o.quote.estimate.profit)} / týden · návratnost ${o.quote.estimate.payback} týdnů</p><small>T${o.quote.week} · ${esc({pending:'Čeká na rozhodnutí',approved:'Schváleno',rejected:'Odmítnuto',expired:'Pověření změněno'}[o.status])}</small><div class="actions">${o.status==='pending'?`<button class="primary" data-gr-offer8="${o.id}">Aktualizovat a posoudit</button><button class="quiet" data-gr-reject8="${o.id}">Odmítnout</button>`:o.project?`<button class="soft" data-gr-project8="${o.project}">Průběh skutečné přípravy</button>`:''}</div></article>`).join('')||'<p class="sub">Žádná nabídka. Pokud adresy nesplňují podmínky, ředitel je nenavrhuje.</p>'}`;el('grExpansionPolicy8').onclick=grExpansionPolicy8;if(el('grExpansionPeople8'))el('grExpansionPeople8').onclick=()=>{el('modal').close();goto('people');};document.querySelectorAll('[data-gr-propose8]').forEach(b=>b.onclick=()=>grToast8(()=>prepareExpansion8(b.dataset.grPropose8),()=>growthDialog8('expansion')));document.querySelectorAll('[data-gr-offer8]').forEach(b=>b.onclick=()=>grExpansionOffer8(b.dataset.grOffer8));document.querySelectorAll('[data-gr-reject8]').forEach(b=>b.onclick=()=>grToast8(()=>decideExpansion8(b.dataset.grReject8,false),()=>growthDialog8('expansion')));document.querySelectorAll('[data-gr-project8]').forEach(b=>b.onclick=()=>openingProjectDialog6(b.dataset.grProject8));}
function grExpansionPolicy8(){const regions=state.regions.filter(r=>r.manager),first=regions[0]?.city,p=state.growth8.delegation.find(x=>x.city===first)||{enabled:true,budget:1500000,minProfit:0,maxPayback:104,reserve:3,standard:null};show(`<h2>Pověření regionálního ředitele</h2><div class="fields">${field('Region',`<select id="grRegion8">${regions.map(r=>option(r.city,r.city+' · '+r.manager.name,first)).join('')}</select>`)}${field('Celkový limit schválených startů',`<input id="grExpansionBudget8" type="number" min="0" max="20000000" value="${p.budget}">`)}${field('Minimální model zisku / týden',`<input id="grExpansionProfit8" type="number" min="-100000" max="1000000" value="${p.minProfit}">`)}${field('Nejdelší návratnost · týdny',`<input id="grExpansionPayback8" type="number" min="1" max="520" value="${p.maxPayback}">`)}${field('Rezerva stávající firmy · týdny',`<input id="grExpansionReserve8" type="number" min="1" max="8" value="${p.reserve}">`)}${field('Standard vybavení a menu',`<select id="grExpansionStandard8"><option value="">Startovací kavárna</option>${state.growth8.standards.map(s=>option(s.id,s.name,p.standard)).join('')}</select>`)}</div><label class="gr-check8"><input type="checkbox" id="grExpansionEnabled8" ${p.enabled?'checked':''}> Ředitel připravuje nabídky</label><button class="primary" id="grSaveExpansion8">Uložit pověření</button>`);el('grRegion8').onchange=()=>{const p=state.growth8.delegation.find(x=>x.city===el('grRegion8').value);if(p){for(const [field,k] of [['Budget','budget'],['Profit','minProfit'],['Payback','maxPayback'],['Reserve','reserve'],['Standard','standard']])el('grExpansion'+field+'8').value=p[k]??'';el('grExpansionEnabled8').checked=p.enabled;}};el('grSaveExpansion8').onclick=()=>grToast8(()=>setExpansion8(el('grRegion8').value,{enabled:el('grExpansionEnabled8').checked,budget:Number(el('grExpansionBudget8').value),minProfit:Number(el('grExpansionProfit8').value),maxPayback:Number(el('grExpansionPayback8').value),reserve:Number(el('grExpansionReserve8').value),standard:el('grExpansionStandard8').value||null}),()=>growthDialog8('expansion'));}
function grExpansionOffer8(id){try{const q=refreshExpansion8(id);persist();show(`<h2>${esc(loc(q.id).name)} · nabídka ${esc(q.author)}</h2>${rows([['Platba nyní',money(q.opening.cost)],['Celá příprava, zásoby a rezerva pobočky',money(q.funding.required)],['Rezerva stávající firmy',money(q.reserved)],['Celkem potřebuješ',money(q.required)],['Model místního zisku',money(q.estimate.profit)+'/týden'],['Návratnost',q.estimate.payback+' týdnů']])}<p class="sub">${esc(q.estimate.assumption)}. Návratnost nezahrnuje centrálu a daň celé firmy. Pověření od ${money(q.policy.minProfit)} zisku, do ${q.policy.maxPayback} týdnů. Skutečný výsledek ovlivní cena, počasí, konkurence a sdílená káva.</p><button class="primary" id="grApproveExpansion8" ${!q.safe?'disabled':''}>Schválit a zahájit přípravu</button>${!q.safe?'<p class="bad">Současná nabídka nesplňuje pověření nebo rezervu.</p>':''}`);el('grApproveExpansion8').onclick=()=>confirmAction('Schválit expanzi?',q.author+' · '+loc(q.id).name+' · '+money(q.opening.cost)+' nyní. Schvaluješ přípravu a průběžné zásobení z celého rozpočtu '+money(q.required)+'.',()=>decideExpansion8(id,true,q),'Schválit a zaplatit');}catch(e){toast(e.message);}}
