function leadershipRows9(p){const q=p.accepted?.quote||p.quote,a=p.actual,fmt=(k,v)=>v===null?'—':['profit','cash','debt','branchProfit'].includes(k)?money(v):number(v,['quality','gap'].includes(k)?1:0),items=[['Výsledek firmy','profit'],['Obsloužení hosté','served'],['Kvalita podané kávy','quality'],['Hotovost na konci týdne','cash']];
 if(p.action.kind==='branch')items.push(['Výsledek pobočky','branchProfit'],['Hosté pobočky','branchServed']);if(p.role==='hr')items.push(['Neobsazená místa ve směnách','gap']);if(p.role==='finance')items.push(['Bankovní jistina','debt']);if(p.role==='product')items.push(['Výzkum receptury','research']);if(p.role==='it')items.push(['Dokončení projektu · %','progress']);
 return `<div class="leadership-table9"><table><caption>Týden T${q.week} · model a pozdější skutečnost</caption><thead><tr><th scope="col">Ukazatel</th><th scope="col">Beze změny</th><th scope="col">Se zásahem</th><th scope="col">Skutečnost</th></tr></thead><tbody>${items.map(([name,k])=>`<tr><th scope="row">${name}</th><td>${fmt(k,q.before[k])}</td><td>${fmt(k,q.after[k])}</td><td>${a?fmt(k,a[k]):'Čeká na týden'}</td></tr>`).join('')}</tbody></table></div>`;
}
function leadershipDialog9(meetingId){
 const meetings=state.leadership9.meetings,m=meetings.find(m=>m.id===meetingId)||meetings.at(-1),canPrepare=!meetings.some(m=>m.week===state.week),stamp=leadershipStamp9();
 show(`<span class="eyelabel">VEDENÍ FIRMY</span><h2>Porada ředitelů</h2><p>Každý návrh má konkrétního autora, cenu a odhad z celé rozehrané firmy. Rozhoduješ o každém zvlášť.</p>${canPrepare?`<details class="card leadership-prepare9" ${m?'':'open'}><summary>Připravit poradu T${state.week}</summary><div class="fields">${field('Limit jednoho zásahu včetně nového týdne',input('leadershipBudget9',100000,0,1000000,1000))}${field('Chráněná rezerva · týdny',input('leadershipReserve9',3,1,8,1))}</div><button class="primary" id="leadershipPrepare9">Vyžádat návrhy vedení</button><small>Potřebuješ uzavřený provozní týden vlastní kavárny, jmenní ředitele a pracovníky jejich oddělení. Příprava návrhů nic nekupuje.</small></details>`:''}${meetings.length?field('Porada a archiv',`<select id="leadershipMeeting9">${meetings.slice().reverse().map(x=>option(x.id,'T'+x.week+' · '+x.proposals.length+' návrhů',m.id)).join('')}</select>`):''}${m?`<p class="sub">Limit ${money(m.budget)} na jeden návrh · rezerva ${m.reserve} týdnů závazků a blízké faktury. Schválení jednoho zásahu změní podmínky dalších nabídek.</p>${m.proposals.map(p=>{const q=p.accepted?.quote||p.quote,stale=p.status==='pending'&&q.stamp!==stamp,label={pending:'Čeká na rozhodnutí',approved:p.actual?'Vyhodnoceno':'Schváleno · čeká na skutečný týden',rejected:'Odmítnuto',expired:'Platnost skončila po týdnu'}[p.status];return `<details class="card leadership-proposal9" ${p.id===m.proposals[0].id?'open':''}><summary><span class="eyelabel">${TN_DEPARTMENTS7[p.role].name} · ${label}</span><strong>${esc(p.author)} · ${esc(p.action.kind==='branch'?p.action.change.label:p.action.label)}</strong><span>${money(q.cost)} nyní · +${money(q.weekly)} týdně · model změny výsledku ${money(q.after.profit-q.before.profit)}</span></summary><h3>${esc(p.author)}</h3><strong>${esc(p.action.kind==='branch'?p.action.change.label:p.action.label)}</strong>${p.action.kind==='branch'?`<p>${esc(loc(p.action.target).name)}</p>`:''}<p>${esc(p.reason)}</p>${rows([['Platba nyní',money(q.cost)],['Nový pravidelný závazek týdně',money(q.weekly)],['Chráněná hotovost',money(q.reserved)]])}${leadershipRows9(p)}${p.status==='pending'?`<div class="actions"><button class="primary" data-leadership-approve9="${p.id}" ${!q.safe||stale?'disabled':''}>Schválit přesnou nabídku</button><button class="soft" data-leadership-refresh9="${p.id}">Přepočítat nabídku</button><button class="quiet" data-leadership-reject9="${p.id}">Odmítnout</button></div>${stale?'<p class="bad">Firma se změnila. Před schválením přepočítej návrh.</p>':!q.safe?'<p class="bad">Návrh překračuje limit nebo provozní rezervu.</p>':''}`:''}${p.actual?`<p class="sub">Rozdíl výsledku firmy proti odhadu ${money(p.actual.profit-q.after.profit)}. Skutečnost zahrnuje také ostatní schválené kroky, konkurenci a události týdne; nejde o izolovaný důkaz účinku tohoto zásahu.</p>`:''}</details>`;}).join('')}${m.absent.length?`<h3>Bez návrhu</h3>${m.absent.map(x=>`<p><strong>${TN_DEPARTMENTS7[x.role].name}:</strong> ${esc(x.reason)}</p>`).join('')}`:''}`:'<p class="sub">Zatím nemáš žádnou poradu. První kavárnu můžeš řídit jako zakladatel; kancelář a vedení pořiď až podle rozpočtu.</p>'}<p class="sub">Model odehraje jeden týden kopie skutečné firmy s placeným provozem a fyzickými zásobami. Zachovává dnešní automatická pravidla. Odhady různých návrhů se nesčítají; náklady týmu a ředitelů jsou už v celkovém výsledku. Minulé schválené nabídky a výsledky zůstávají uložené.</p><button class="soft" id="leadershipPeople9">Obsadit vedení a týmy</button>`);
 if(el('leadershipPrepare9'))el('leadershipPrepare9').onclick=()=>{const budget=Number(el('leadershipBudget9').value),reserve=Number(el('leadershipReserve9').value);grToast8(()=>prepareLeadership9(budget,reserve),()=>leadershipDialog9());};
 if(el('leadershipMeeting9'))el('leadershipMeeting9').onchange=()=>leadershipDialog9(el('leadershipMeeting9').value);
 el('leadershipPeople9').onclick=()=>{el('modal').close();goto('organization');};
 document.querySelectorAll('[data-leadership-refresh9]').forEach(b=>b.onclick=()=>grToast8(()=>refreshLeadership9(b.dataset.leadershipRefresh9),()=>leadershipDialog9(m.id)));
 document.querySelectorAll('[data-leadership-reject9]').forEach(b=>b.onclick=()=>grToast8(()=>decideLeadership9(b.dataset.leadershipReject9,false),()=>leadershipDialog9(m.id)));
 document.querySelectorAll('[data-leadership-approve9]').forEach(b=>b.onclick=()=>{const {p}=leadershipProposal9(b.dataset.leadershipApprove9),q=grCopy8(p.quote);confirmAction('Schválit návrh vedení?',p.author+': '+(p.action.kind==='branch'?p.action.change.label:p.action.label)+' · '+money(q.cost)+' nyní, +'+money(q.weekly)+' pravidelně týdně. Po týdnu porovnáš odhad se skutečností.',()=>decideLeadership9(p.id,true,q),'Schválit a provést');});
}
